/* Shared helpers. Data lives in data.js (window.CASCADIA), generated by make_site_data.py */
const D = window.CASCADIA;
const ICON = {bear:'🐻',elk:'🦌',salmon:'🐟',hawk:'🦅',fox:'🦊',mountain:'⛰️',forest:'🌲',prairie:'🌾',wetland:'🪷',river:'🌊',nature:'🌰'};
const LABEL = s => s.charAt(0).toUpperCase()+s.slice(1);
const NAME = id => (D.names && D.names[id]) || id;
const PALETTE = ['#2f6f4e','#c0703a','#3f7f9a','#b5933a','#8a4f7d','#6b8f4e','#a2462e','#4f6d8a','#7a6a3a','#5a8f86','#9a6b4f','#556b2f','#8b7d6b'];
const ORDER = Object.values(D.players).sort((a,b)=>b.games-a.games||b.wins-a.wins||a.id.localeCompare(b.id)).map(p=>p.id);
const COLOR = id => PALETTE[ORDER.indexOf(id) % PALETTE.length];
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
function fmtDate(iso, withDow=true){ const [y,m,d]=iso.split('-').map(Number); const dt=new Date(Date.UTC(y,m-1,d));
  return (withDow?DOW[dt.getUTCDay()]+' ':'')+d+' '+MONTHS[m-1]+' '+y; }
function fmtMonth(ym){ const [y,m]=ym.split('-').map(Number); return ['January','February','March','April','May','June','July','August','September','October','November','December'][m-1]+' '+y; }
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fx = (v,d=1) => v==null?'–':(Math.round(v*10**d)/10**d).toFixed(d);
const sgn = (v,d=1) => v==null?'–':(v>0?'+':'')+fx(v,d);
const plink = id => `<a href="player.html?p=${encodeURIComponent(id)}" style="color:${COLOR(id)}">${esc(NAME(id))}</a>`;
const ord = n => n+(['th','st','nd','rd'][(n%100-20)%10]||['th','st','nd','rd'][n%100]||'th');
function approxTag(g){ return g.date_uncertain ? `<span class="pill approx" title="${esc('Written on the scorecard as “'+g.date_raw+'”. '+(g.date_note||''))}">date approx.</span>` : ''; }
function renderChrome(active){
  const nav = [['index.html','Game log','log'],['players.html','Players','players'],['player.html','Player page','player'],['insights.html','Insights','insights']];
  document.body.insertAdjacentHTML('afterbegin', `<header class="site"><div class="bar">
    <a class="brand" href="index.html"><span class="hex">🌲</span>Cascadia Night Stats</a>
    <nav class="main">${nav.map(([h,t,k])=>`<a href="${h}" class="${k===active?'active':''}">${t}</a>`).join('')}</nav></div></header>`);
  const i=D.insights;
  document.body.insertAdjacentHTML('beforeend', `<footer>🐻 🦌 🐟 🦅 🦊 &nbsp;Scores were transcribed by hand from photos of our paper scorecards (${i.n_games} games, ${fmtDate(i.date_range[0],false)} to ${fmtDate(i.date_range[1],false)}), so a few digits or dates may be off. Cells shown as <span class="unk">?</span> couldn’t be read.</footer>`);
}
if (window.Chart){
  Chart.defaults.font.family = '"Nunito","Segoe UI",system-ui,sans-serif';
  Chart.defaults.color = '#5c574a';
  Chart.defaults.borderColor = 'rgba(139,94,60,.15)';
  Chart.defaults.maintainAspectRatio = false;
}
const NAMEIFY = t => String(t).replace(/\b([A-Z][a-z])\b(?!")/g,(m,id)=>D.players[id]?NAME(id):m);
